     * Scopes: campaigns:update.
     *
     * @param  ?string  $idempotencyKey  Repeat a request safely: SendSeven answers a repeat with the first result. One is generated when omitted.
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/Email%20Campaigns/remove_failed_email_campaign_recipients_api_v1_email_campaigns__campaign_id__recipients_remove_failed_post
     */
    public function removeFailedRecipients(string $campaignId, ?string $idempotencyKey = null): RemoveFailedRecipients
    {
        $response = $this->connector->send(new Request(
            Method::Post,
            '/email-campaigns/'.Payload::segment($campaignId).'/recipients/remove-failed',
            headers: $idempotencyKey === null ? [] : ['Idempotency-Key' => $idempotencyKey],
        ));

        return RemoveFailedRecipients::fromArray($response->data());
    }

    /**
     * Delete Email Campaign Recipient.
     *
     * Remove a single recipient from an email campaign.
     *
     * Hard-deletes the per-recipient row (tenant + campaign ownership validated), then recomputes the
     * email campaign's denormalized counters.
     *
     * - HTTP 409 "This recipient is queued for sending and cannot be removed while the campaign is
     * sending or paused. Cancel the campaign first." for a queued recipient of a sending / throttled /
     * paused campaign (its email may already be on its way).
     *
     * Scopes: campaigns:update.
     *
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/Email%20Campaigns/delete_email_campaign_recipient_api_v1_email_campaigns__campaign_id__recipients__recipient_id__delete
     */
    public function deleteRecipient(string $campaignId, string $recipientId): Delete
    {
        $response = $this->connector->send(new Request(
            Method::Delete,
            '/email-campaigns/'.Payload::segment($campaignId).'/recipients/'.Payload::segment($recipientId),
        ));

        return Delete::fromArray($response->data());
    }

    /**
     * Retry Email Campaign Recipient.
     *
     * Retry a single failed recipient of an email campaign.
     *
     * Calls the retry execution in EmailCampaignService.retry_single_recipient and returns the updated
     * recipient item so the UI can update the row inline.
     *
     * - Recipient not found -> 404 - Campaign not completed, failed or paused -> 409 "Recipients can
     * only be retried on a completed, failed or paused campaign" - Recipient reported the email as
     * spam (complained) -> 409 "This recipient reported the email as spam and cannot be sent to again"
     * - Recipient not retryable in its current state (e.g. not failed) -> 409 - Recipient permanently
     * undeliverable (hard email bounce) -> 422
     *
     * Scopes: campaigns:send.
     *
     * @param  ?string  $idempotencyKey  Repeat a request safely: SendSeven answers a repeat with the first result. One is generated when omitted.
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/Email%20Campaigns/retry_email_campaign_recipient_api_v1_email_campaigns__campaign_id__recipients__recipient_id__retry_post
     */
    public function retryRecipient(
        string $campaignId,
        string $recipientId,
        ?string $idempotencyKey = null,
    ): CampaignRecipientItem {
        $response = $this->connector->send(new Request(
            Method::Post,
            '/email-campaigns/'.Payload::segment($campaignId).'/recipients/'.Payload::segment($recipientId).'/retry',
            headers: $idempotencyKey === null ? [] : ['Idempotency-Key' => $idempotencyKey],
        ));

        return CampaignRecipientItem::fromArray($response->data());
    }

    /**
     * Unsubscribe Email Campaign Recipient.
     *
     * Opt an email recipient's contact out of this campaign's lists.
     *
     * This is DISTINCT from DELETE /{campaign_id}/recipients/{recipient_id} ("Remove"), which only
     * deletes the per-recipient row and does NOT change subscription state. This endpoint resolves the
     * recipient's contact, computes the campaign's originating list(s) (campaign_lists on the base
     * campaign ∩ the contact's currently-subscribed lists) and opts the contact out of all of them
     * via the subscription chokepoint, writing the opt-out ledger with campaign attribution
     * (method='manual'). {campaign_id} is the EmailCampaign.id (as elsewhere on this router).
     *
     * - Recipient (or its campaign) not found for this tenant -> 404 - Recipient has no linked contact
     * -> 422 - Contact subscribed to none of the campaign's lists (or the campaign targets no lists)
     * -> 200 with an empty unsubscribed_lists - Contact already opted out of all of the campaign's
     * lists -> 200 with already_unsubscribed: true
     *
     * Scopes: campaigns:update.
     *
     * @param  ?string  $idempotencyKey  Repeat a request safely: SendSeven answers a repeat with the first result. One is generated when omitted.
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/Email%20Campaigns/unsubscribe_email_campaign_recipient_api_v1_email_campaigns__campaign_id__recipients__recipient_id__unsubscribe_post
     */
    public function unsubscribeRecipient(
        string $campaignId,
        string $recipientId,
        ?string $idempotencyKey = null,
    ): RecipientUnsubscribe {
        $response = $this->connector->send(new Request(
            Method::Post,
            '/email-campaigns/'.Payload::segment($campaignId).'/recipients/'.Payload::segment($recipientId).'/unsubscribe',
            headers: $idempotencyKey === null ? [] : ['Idempotency-Key' => $idempotencyKey],
        ));

        return RecipientUnsubscribe::fromArray($response->data());
    }

    /**
     * Resume Email Campaign.
     *
     * Resume a paused email campaign
     *
     * Only a paused campaign can be resumed (anything else returns HTTP 400). Sending continues with
     * everyone who has not been sent yet. If a send speed or batch size was saved while the campaign
     * was paused, it applies from now on. A campaign that finished a batch (throttle_reason =
     * "batch_complete") sends its next batch, exactly like POST /email-campaigns/{id}/send-next-batch
     * with an empty body. A campaign sent in batches that ended as completed or failed while
     * recipients were still waiting is re-opened the same way. HTTP 422 send_pacing_unavailable while
     * sending at a set speed or in batches is briefly unavailable.
     *
     * Scopes: campaigns:send.
     *
     * @param  ?string  $idempotencyKey  Repeat a request safely: SendSeven answers a repeat with the first result. One is generated when omitted.
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/Email%20Campaigns/resume_email_campaign_api_v1_email_campaigns__campaign_id__resume_post
     */
    public function resume(string $campaignId, ?string $idempotencyKey = null): EmailCampaign
    {
        $response = $this->connector->send(new Request(
            Method::Post,
            '/email-campaigns/'.Payload::segment($campaignId).'/resume',
            headers: $idempotencyKey === null ? [] : ['Idempotency-Key' => $idempotencyKey],
        ));

        return EmailCampaign::fromArray($response->data());
    }

    /**
     * Schedule Campaign.
     *
     * Schedule an email campaign for future sending.
     *
     * Accepts a local datetime and IANA timezone string. The backend converts to UTC for storage. The
     * original timezone is preserved for display purposes.
     *
     * The scheduled time must be at least 5 minutes in the future.
     *
     * Scopes: campaigns:update.
     *
     * @param  DateTimeInterface|string  $scheduledAt  Local datetime in the given timezone (naive or with offset)
     * @param  string  $timezone  IANA timezone (e.g. 'Europe/Berlin', 'America/New_York')
     * @param  ?string  $idempotencyKey  Repeat a request safely: SendSeven answers a repeat with the first result. One is generated when omitted.
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/Email%20Campaigns/schedule_campaign_api_v1_email_campaigns__campaign_id__schedule_post
     */
    public function schedule(
        string $campaignId,
        DateTimeInterface|string $scheduledAt,
        string $timezone,
        ?string $idempotencyKey = null,
    ): EmailCampaign {
        $response = $this->connector->send(new Request(
            Method::Post,
            '/email-campaigns/'.Payload::segment($campaignId).'/schedule',
            body: Payload::body(['scheduled_at' => $scheduledAt, 'timezone' => $timezone]),
            headers: $idempotencyKey === null ? [] : ['Idempotency-Key' => $idempotencyKey],
        ));

        return EmailCampaign::fromArray($response->data());
    }

    /**
     * Send Campaign.
     *
     * Send or schedule email campaign.
     *
     * - If send_test=true, sends to test_emails only (TODO) - Otherwise, queues campaign to Pub/Sub
     * for async sending - Updates campaign status to SENDING - Deducts balance upfront (prepaid model)
     * - Send speed and batches: with a send_rate_limit and/or send_batch_size saved on the campaign,
     * the emails go out at that speed and in batches of that size. After each batch the campaign
     * pauses (status = "paused", throttle_reason = "batch_complete") until POST
     * /email-campaigns/{id}/send-next-batch. A saved batch size that cannot be used returns HTTP 422
     * {code, message} before anything is sent (send_pacing_unavailable, send_batch_size_invalid). -
     * HTTP 409 "This campaign is already being sent" when the campaign is already sending / throttled
     * / paused, or a concurrent request (a second click, the scheduled send) started it first --
     * nothing is queued twice. HTTP 409 "This campaign was paused or cancelled while it was being
     * prepared for sending. Refresh and try again." when that happened during the send.
     *
     * Scopes: campaigns:send.
     *
     * @param  ?bool  $sendTest  Send test to specific addresses
     * @param  list<string>|null  $testEmails  Test email addresses
     * @param  ?string  $idempotencyKey  Repeat a request safely: SendSeven answers a repeat with the first result. One is generated when omitted.
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/Email%20Campaigns/send_campaign_api_v1_email_campaigns__campaign_id__send_post
     */
    public function send(
        string $campaignId,
        ?bool $sendTest = null,
        ?array $testEmails = null,
        ?string $idempotencyKey = null,
    ): SendCampaign {
        $response = $this->connector->send(new Request(
            Method::Post,
            '/email-campaigns/'.Payload::segment($campaignId).'/send',
            body: Payload::body(['send_test' => $sendTest, 'test_emails' => $testEmails]),
            headers: $idempotencyKey === null ? [] : ['Idempotency-Key' => $idempotencyKey],
        ));

        return SendCampaign::fromArray($response->data());
    }

    /**
     * Send Next Email Batch.
     *
     * Send the next batch of an email campaign sent in batches
     *
     * Only for a campaign that finished a batch: status = "paused" with throttle_reason =
     * "batch_complete", or one that ended as completed / failed while recipients were still waiting
     * (it continues its unfinished batch first, if any). HTTP 422 send_pacing_unavailable while batch
     * sending is briefly unavailable. Anything else returns HTTP 409 {"code":
     * "campaign_not_awaiting_batch", "message": ...} (also when two requests race: only the first one
     * sends a batch).
     *
     * Body (optional): {"batch_size": 500} sends 500 recipients now and saves 500 as the campaign's
     * batch size (1-1,000,000; anything else is HTTP 422 {"code": "send_batch_size_invalid",
     * "message": ...}); {"all_remaining": true} sends everyone who is still waiting. An empty body
     * sends the next batch at the saved batch size. Recipients who unsubscribed, bounced or were
     * suppressed since the campaign was prepared are skipped (skipped_ineligible).
     *
     * Scopes: campaigns:send.
     *
     * @param  array<string, mixed>|null  $body  The request body
     * @param  ?string  $idempotencyKey  Repeat a request safely: SendSeven answers a repeat with the first result. One is generated when omitted.
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/Email%20Campaigns/send_next_email_batch_api_v1_email_campaigns__campaign_id__send_next_batch_post
     */
    public function sendNextBatch(
        string $campaignId,
        ?array $body = null,
        ?string $idempotencyKey = null,
    ): EmailSendNextBatch {
        $response = $this->connector->send(new Request(
            Method::Post,
            '/email-campaigns/'.Payload::segment($campaignId).'/send-next-batch',
            body: $body,
            headers: $idempotencyKey === null ? [] : ['Idempotency-Key' => $idempotencyKey],
        ));

        return EmailSendNextBatch::fromArray($response->data());
    }

    /**
     * Get Email Campaign Send Plan.
     *
     * Send plan of an email campaign: speed, batches and estimated duration
     *
     * Read-only estimate for the campaign's audience at its saved send speed and batch size, or at the
     * values given as query parameters (to preview a change before saving it). eta_seconds estimates
     * the time to send everyone who is left (time paused between batches not included).
     * pacing_available = false means send speed and batches are not available for this account yet.
     *
     * Out-of-range query values return HTTP 422 {code, message} (send_rate_limit_out_of_range,
     * send_batch_size_invalid).
     *
     * Scopes: campaigns:read.
     *
     * @param  ?int  $sendRateLimit  Preview this send speed (emails per minute, 1-60000) instead of the saved one
     * @param  ?int  $sendBatchSize  Preview this batch size (>= 1) instead of the saved one
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/Email%20Campaigns/get_email_campaign_send_plan_api_v1_email_campaigns__campaign_id__send_plan_get
     */
    public function getSendPlan(string $campaignId, ?int $sendRateLimit = null, ?int $sendBatchSize = null): SendPlan
    {
        $response = $this->connector->send(new Request(
            Method::Get,
            '/email-campaigns/'.Payload::segment($campaignId).'/send-plan',
            query: Payload::query(['send_rate_limit' => $sendRateLimit, 'send_batch_size' => $sendBatchSize]),
        ));

        return SendPlan::fromArray($response->data());
    }

    /**
     * Get Campaign Unsubscribes.
     *
     * List recipients who opted out via THIS email campaign's unsubscribe link.
     *
     * Campaign-attributed opt-outs, sourced from unsubscribe_tokens (SHARD) stamped with the
     * email_campaign_id at send time. Ordered by unsubscribed_at DESC, paginated (page/page_size,
     * default 25).
     *
     * Only LINK-method opt-outs exist today; method_counts.keyword is reserved (null) for a future
     * keyword-based source that lands once an events table exists.
     *
     * Scopes: analytics:read.
     *
     * @return Page<AppSchemasEmailCampaignSchemaCampaignUnsubscribeItem>
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/Email%20Campaigns/get_campaign_unsubscribes_api_v1_email_campaigns__campaign_id__unsubscribes_get
     */
    public function getUnsubscribes(string $campaignId, ?int $page = null, ?int $pageSize = null): Page
    {
        $response = $this->connector->send(new Request(
            Method::Get,
            '/email-campaigns/'.Payload::segment($campaignId).'/unsubscribes',
            query: Payload::query(['page' => $page, 'page_size' => $pageSize]),
        ));

        return Hydrate::page($response->data(), AppSchemasEmailCampaignSchemaCampaignUnsubscribeItem::fromArray(...), fn (int $page): Page => $this->getUnsubscribes(campaignId: $campaignId, page: $page, pageSize: $pageSize));
    }
}
